import { readFile, writeFile } from 'node:fs/promises'
import { fileURLToPath } from 'node:url'
import sharp from 'sharp'

const root = new URL('../', import.meta.url)
const symbol = await readFile(new URL('brand/symbol.svg', root), 'utf8')
const wordmark = await readFile(new URL('brand/wordmark.svg', root), 'utf8')
const generated =
  '<!-- Generated by scripts/generate-brand.ts. Edit brand/symbol.svg or brand/wordmark.svg. -->\n'
const themes = [
  { name: 'light', ink: '#4F5B2A', accent: '#B8892D', paper: '#F5EFE3' },
  { name: 'dark', ink: '#B8C58A', accent: '#C4AA73', paper: '#111213' },
]

function recolor(svg: string, ink: string, accent: string) {
  return svg.replaceAll('#4F5B2A', ink).replaceAll('#B8892D', accent)
}

function place(svg: string, x: number, y: number, width: number, height: number) {
  return svg.replace(
    /<svg[^>]*viewBox=/,
    `<svg x="${x}" y="${y}" width="${width}" height="${height}" viewBox=`,
  )
}

let preview =
  '<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="760" viewBox="0 0 1200 760" role="img" aria-label="阅纹折页标志：浅色、深色和小尺寸预览">'
for (const [index, theme] of themes.entries()) {
  const mark = recolor(symbol, theme.ink, theme.accent)
  const lettering = recolor(wordmark, theme.ink, theme.accent)
  const lockup = `<svg xmlns="http://www.w3.org/2000/svg" width="280" height="96" viewBox="0 0 280 96" role="img" aria-label="阅纹">${place(mark, 0, 4, 88, 88)}${place(lettering, 112, 15, 160, 66)}</svg>\n`
  await writeFile(new URL(`brand/logo-mark-${theme.name}.svg`, root), generated + mark)
  await writeFile(new URL(`web/public/brand/logo-mark-${theme.name}.svg`, root), generated + mark)
  await writeFile(new URL(`brand/logo-${theme.name}.svg`, root), generated + lockup)

  const x = index * 600
  preview += `<rect x="${x}" width="600" height="760" fill="${theme.paper}"/>`
  preview += place(mark, x + 188, 96, 224, 224)
  preview += place(lettering, x + 216, 367, 168, 70)
  preview += `<path d="M${x + 64} 506H${x + 536}" stroke="${theme.ink}" opacity=".2"/>`
  for (const [i, size] of [16, 24, 32, 48].entries()) {
    const cx = x + 120 + i * 120
    preview += place(mark, cx - size / 2, 563 - size / 2, size, size)
    preview += `<text x="${cx}" y="616" fill="${theme.ink}" text-anchor="middle" font-family="sans-serif" font-size="12">${size}</text>`
  }
  preview += `<circle cx="${x + 278}" cy="688" r="7" fill="${theme.ink}"/><circle cx="${x + 302}" cy="688" r="7" fill="${theme.accent}"/><circle cx="${x + 326}" cy="688" r="7" fill="${theme.paper}" stroke="${theme.ink}" stroke-width="1"/>`
}
preview += '</svg>\n'
await writeFile(
  new URL('brand/logo-mark-mono.svg', root),
  generated + recolor(symbol, 'currentColor', 'currentColor'),
)
await writeFile(new URL('brand/brand-preview.svg', root), generated + preview)
await sharp(Buffer.from(preview))
  .png()
  .toFile(fileURLToPath(new URL('brand/brand-preview.png', root)))
